mapper.select:
SELECT
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'SUCCESS'
         AND paid_at >= #{rangeStart}
         AND paid_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS successCount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'SUCCESS'
         AND paid_at >= #{rangeStart}
         AND paid_at < #{rangeEnd}
        THEN COALESCE(paid_amount, amount) ELSE 0 END), 0) AS successAmount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'SUCCESS'
         AND paid_at >= #{rangeStart}
         AND paid_at < #{rangeEnd}
        THEN merchant_fee_amount ELSE 0 END), 0) AS feeAmount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'FAILED'
         AND failed_at >= #{rangeStart}
         AND failed_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS failedCount,
    COALESCE(SUM(CASE
        WHEN status = 'CLOSED'
         AND closed_at >= #{rangeStart}
         AND closed_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS closedCount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'PROCESSING'
        THEN 1 ELSE 0 END), 0) AS processingCount
FROM payin_order
WHERE tenant_id = #{tenantId}
  AND merchant_id = #{merchantId}
  AND currency = #{currency}

SELECT
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'SUCCESS'
         AND COALESCE(completed_at, updated_at) >= #{rangeStart}
         AND COALESCE(completed_at, updated_at) < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS successCount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'SUCCESS'
         AND COALESCE(completed_at, updated_at) >= #{rangeStart}
         AND COALESCE(completed_at, updated_at) < #{rangeEnd}
        THEN amount ELSE 0 END), 0) AS successAmount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'SUCCESS'
         AND COALESCE(completed_at, updated_at) >= #{rangeStart}
         AND COALESCE(completed_at, updated_at) < #{rangeEnd}
        THEN merchant_fee_amount ELSE 0 END), 0) AS feeAmount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'FAILED'
         AND failed_at >= #{rangeStart}
         AND failed_at < #{rangeEnd}
        THEN 1 ELSE 0 END), 0) AS failedCount,
    COALESCE(SUM(CASE
        WHEN merchant_status_code = 'PROCESSING'
        THEN 1 ELSE 0 END), 0) AS processingCount
FROM payout_order
WHERE tenant_id = #{tenantId}
  AND merchant_id = #{merchantId}
  AND currency = #{currency}

SELECT
    0 AS manualReview,
    (
        SELECT COUNT(1)
        FROM payin_order
        WHERE tenant_id = #{tenantId}
          AND merchant_id = #{merchantId}
          AND currency = #{currency}
          AND merchant_notify_status = 'FAILED'
    ) + (
        SELECT COUNT(1)
        FROM payout_order
        WHERE tenant_id = #{tenantId}
          AND merchant_id = #{merchantId}
          AND currency = #{currency}
          AND merchant_notify_status = 'FAILED'
    ) AS notifyFailed,
    0 AS settleDue,
    (
        SELECT COUNT(1)
        FROM payin_order
        WHERE tenant_id = #{tenantId}
          AND merchant_id = #{merchantId}
          AND currency = #{currency}
          AND merchant_status_code = 'PROCESSING'
    ) AS processingPay,
    (
        SELECT COUNT(1)
        FROM payout_order
        WHERE tenant_id = #{tenantId}
          AND merchant_id = #{merchantId}
          AND currency = #{currency}
          AND merchant_status_code = 'PROCESSING'
    ) AS processingPayout

SELECT
    DATE_FORMAT(CONVERT_TZ(paid_at, '+00:00', #{tzOffset}), '%Y-%m-%d') AS date,
    COUNT(1) AS payInCount,
    COALESCE(SUM(COALESCE(paid_amount, amount)), 0) AS payInAmount
FROM payin_order
WHERE tenant_id = #{tenantId}
  AND merchant_id = #{merchantId}
  AND currency = #{currency}
  AND status = 'SUCCESS'
  AND paid_at >= #{rangeStart}
  AND paid_at < #{rangeEnd}
GROUP BY DATE_FORMAT(CONVERT_TZ(paid_at, '+00:00', #{tzOffset}), '%Y-%m-%d')
ORDER BY date ASC

SELECT
    TO_CHAR(paid_at + CAST(#{tzOffset} AS interval), 'YYYY-MM-DD') AS date,
    COUNT(1) AS payInCount,
    COALESCE(SUM(COALESCE(paid_amount, amount)), 0) AS payInAmount
FROM payin_order
WHERE tenant_id = #{tenantId}
  AND merchant_id = #{merchantId}
  AND currency = #{currency}
  AND status = 'SUCCESS'
  AND paid_at >= #{rangeStart}
  AND paid_at < #{rangeEnd}
GROUP BY TO_CHAR(paid_at + CAST(#{tzOffset} AS interval), 'YYYY-MM-DD')
ORDER BY date ASC

SELECT
    DATE_FORMAT(CONVERT_TZ(COALESCE(completed_at, updated_at), '+00:00', #{tzOffset}), '%Y-%m-%d') AS date,
    COUNT(1) AS payOutCount,
    COALESCE(SUM(amount), 0) AS payOutAmount
FROM payout_order
WHERE tenant_id = #{tenantId}
  AND merchant_id = #{merchantId}
  AND currency = #{currency}
  AND status = 'SUCCESS'
  AND COALESCE(completed_at, updated_at) >= #{rangeStart}
  AND COALESCE(completed_at, updated_at) < #{rangeEnd}
GROUP BY DATE_FORMAT(CONVERT_TZ(COALESCE(completed_at, updated_at), '+00:00', #{tzOffset}), '%Y-%m-%d')
ORDER BY date ASC

SELECT
    TO_CHAR(COALESCE(completed_at, updated_at) + CAST(#{tzOffset} AS interval), 'YYYY-MM-DD') AS date,
    COUNT(1) AS payOutCount,
    COALESCE(SUM(amount), 0) AS payOutAmount
FROM payout_order
WHERE tenant_id = #{tenantId}
  AND merchant_id = #{merchantId}
  AND currency = #{currency}
  AND status = 'SUCCESS'
  AND COALESCE(completed_at, updated_at) >= #{rangeStart}
  AND COALESCE(completed_at, updated_at) < #{rangeEnd}
GROUP BY TO_CHAR(COALESCE(completed_at, updated_at) + CAST(#{tzOffset} AS interval), 'YYYY-MM-DD')
ORDER BY date ASC
